import{_ as a,o as e,c as p,a3 as s}from"./chunks/framework.jVlskimI.js";const r="/assets/1-6.Cf4O5Yrj.png",o="/assets/1.D9C0wqI0.png",i="/assets/1-3.CIpwWQrT.png",l="/assets/1-8.C5nUWPfu.png",n="/assets/1-7.BVs9lAIi.png",c="/assets/1-4.CkPY2PC7.png",m="/assets/1-5.D5YfUxiY.png",h="/assets/1-2.BYIb68iI.png",k=JSON.parse('{"title":"LeviTPSystem - 传送系统","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/1.md","filePath":"plugins/1.md"}'),d={name:"plugins/1.md"};function g(u,t,_,b,f,x){return e(),p("div",{"data-pagefind-body":!0},t[0]||(t[0]=[s('<h1 id="levitpsystem-传送系统" tabindex="-1">LeviTPSystem - 传送系统 <a class="header-anchor" href="#levitpsystem-传送系统" aria-label="Permalink to &quot;LeviTPSystem - 传送系统&quot;">​</a></h1><blockquote><p>玩家们可以使用这个插件来进行传送等系列功能</p></blockquote><h2 id="插件用法" tabindex="-1">插件用法 <a class="header-anchor" href="#插件用法" aria-label="Permalink to &quot;插件用法&quot;">​</a></h2><h2 id="指令" tabindex="-1">指令： <a class="header-anchor" href="#指令" aria-label="Permalink to &quot;指令：&quot;">​</a></h2><p>/tps 打开主菜单</p><p><img src="'+r+'" alt="alt text"><img src="'+o+'" alt="alt text"></p><h2 id="tpa-命令" tabindex="-1">Tpa 命令: <a class="header-anchor" href="#tpa-命令" aria-label="Permalink to &quot;Tpa 命令:&quot;">​</a></h2><p>/tps tpa 打开 Tpa GUI</p><p>/tps tpa accept 接受一个 Tpa 请求</p><p>/tps tpa deny 拒绝一个 Tpa 请求</p><p>/tps tpa here 玩家名称 发起 Tpa 将目标玩家传送到我这</p><p>/tps tpa to 玩家名称 发起 Tpa 传送到目标玩家</p><p><img src="'+i+'" alt="alt text"></p><h2 id="home-命令" tabindex="-1">Home 命令 <a class="header-anchor" href="#home-命令" aria-label="Permalink to &quot;Home 命令&quot;">​</a></h2><p>/tps home 家园传送点 GUI</p><p>/tps home add &lt;name: string&gt; 添加一个家</p><p>/tps home del &lt;name: string&gt; 删除一个家</p><p>/tps home go &lt;name: string&gt; 前往家</p><p>/tps home list 列出所有家 <img src="'+l+'" alt="alt text"></p><h2 id="公共传送点-命令" tabindex="-1">公共传送点 命令 <a class="header-anchor" href="#公共传送点-命令" aria-label="Permalink to &quot;公共传送点 命令&quot;">​</a></h2><p>/tps warp 公共传送点 GUI</p><p>/tps warp add &lt;name: string&gt; 添加一个公共传送点（权限组允许）</p><p>/tps warp del &lt;name: string&gt; 删除一个公共传送点（权限组允许）</p><p>/tps warp go &lt;name: string&gt; 前往公共传送点</p><p>/tps warp list 列出所有公共传送点 <img src="'+n+'" alt="alt text"></p><h2 id="back-命令" tabindex="-1">Back 命令： <a class="header-anchor" href="#back-命令" aria-label="Permalink to &quot;Back 命令：&quot;">​</a></h2><p>/tps back 返回死亡点 GUI</p><p><img src="'+c+'" alt="alt text"></p><h2 id="其他命令" tabindex="-1">其他命令： <a class="header-anchor" href="#其他命令" aria-label="Permalink to &quot;其他命令：&quot;">​</a></h2><p>/tps death 查询死亡信息</p><p><img src="'+m+'" alt="alt text"></p><p>/tps rule 打开规则配置</p><p><img src="'+h+'" alt="alt text"></p>',33)]))}const P=a(d,[["render",g]]);export{k as __pageData,P as default};
